#include <bits/stdc++.h>
using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n;
    cin >> n;

    // Query all pairs (i, j) where i < j
    // query(i,j) returns parity of inversions in subarray [i,j]
    // For i < j, this tells us if p[i] > p[j] (since there's only one pair)
    vector<vector<int>> inv(n + 2, vector<int>(n + 2, 0));

    for (int i = 1; i <= n; i++) {
        for (int j = i + 1; j <= n; j++) {
            cout << 0 << " " << i << " " << j << endl;
            cout.flush();
            int resp;
            cin >> resp;
            inv[i][j] = resp;
        }
    }

    // Compute the rank (number of smaller elements to the right + 1) for each position
    // rank[i] = 1 + sum of inv[i][j] for all j > i
    vector<int> rank(n + 1);
    for (int i = 1; i <= n; i++) {
        rank[i] = 1;
        for (int j = i + 1; j <= n; j++) {
            rank[i] += inv[i][j];
        }
    }

    // Build the permutation: position with rank k gets value k
    vector<int> ans(n + 1);
    for (int i = 1; i <= n; i++) {
        ans[rank[i]] = i;
    }

    // Output the answer
    cout << 1;
    for (int i = 1; i <= n; i++) {
        cout << " " << ans[i];
    }
    cout << endl;

    return 0;
}
